@startuml

class Location {
  + Address : string
}

class Driver {
  + FirstName : string
  + LastName : string
}

abstract class Vehicle {
  + VehicleNumber : string
}

class Truck {
  + Weight : double
}

class Car {
  + Seats : int
}

class Van {}

class Order {
  + OriginLocation : Location
  + DestinationLocation : Location
  + AssignedDriver : Driver
  + DateOfExecution : date
}

Vehicle "1" -- "*" Driver : drivenBy

Truck --|> Vehicle
Car --|> Vehicle
Van --|> Vehicle

Driver "0..1" -- "*" Order : carriesOut

@enduml

